package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A claim as the screen shows it; `deferred` as of the sheet's today, and `deferredUntil` the date it was last deferred until (null when never deferred), and `splitFrom` the number of the claim it was split off (null when none), and `lateEntry` whether it was added while its period was soft-closed, and `reminded` the last day a reminder was written (null when never), and `ref` its external reference (null when none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        java.util.List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String reminded, String ref) {

    /** The claim with its status log, oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, LocalDate today) {
        boolean deferred = claim.isDeferredOn(today);
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(), claim.getCorrects(),
                claim.getDueBy().toString(), log, deferred, claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                claim.getProofs(), claim.getSplitFrom(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.session.ChangedBy;

/**
 * A claim's audit record: the event, sheet, user, then person, amount (two decimals) and date, and
 * the claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    static String line(String event, Claim claim, ChangedBy by, String personName) {
        return line(event, claim, by, personName, claim.getNumber());
    }

    /** The CLAIM_ADDED record: the claim's line, then its reference when it has one. */
    static String added(Claim claim, ChangedBy by, String personName) {
        return line("CLAIM_ADDED", claim, by, personName) + (claim.getRef() == null ? "" : " ref=" + claim.getRef());
    }

    static String line(String event, Claim claim, ChangedBy by, String personName, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + by.name() + " person=" + personName + " amount="
                + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim (date blank: the sheet's entry date, else its today), due by the terms-th business day after its date (skipping Saturdays, Sundays and the sheet's holidays), with the terms in force on that date for its person (their own, else their grade's on that date, else the sheet's) fixed from now on; a late entry when that due-by is in a soft-closed period. */
public class BuildClaim {
    public void build(@Val Person person, @Val ClaimInput input, ClaimRepository repository,
            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, HolidayRepository holidays, Out<Claim> claim) {
        LocalDate date = input.date() != null ? input.date()
                : settings.entryDate(person.getSheetId(), sheets.today(person.getSheetId()));
        Claim added = repository.insert(person.getSheetId(), person.getId(), input.amount(), date, input.note(),
                input.corrects(), input.ref(), terms(person, date, settings));
        if (periods.softClosedOn(person.getSheetId(), added.getDueBy())) {
            repository.markLate(added);
        }
        claim.set(added);
    }

    /** The terms a claim of the person dated {@code date} is fixed with: those in force then for them. */
    static int terms(Person person, LocalDate date, SettingRepository settings) {
        return settings.dated(person.getSheetId()).terms(person, date);
    }

    /**
     * The due-by a claim of the person dated {@code date} would have: the terms-th business day after its date, by the
     * sheet's holidays as they stand now.
     */
    static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.dueBy(person.getSheetId(), date, terms(person, date, settings));
    }
}
